script:
doc.has_summary_dismissal = 0

for row in doc.charge_description:
    if row.prescribed_sanction == "Summary Dismissal":
        doc.has_summary_dismissal = 1
        break

# Fires when workflow enters "Disciplinary Committee" state
# Copies charge_description rows into hearing_outcome table

if doc.workflow_state == "Disciplinary Committee":
    # Only populate if hearing_outcome is empty to avoid overwriting
    if not doc.hearing_outcome:
        for charge in doc.charge_description:
            doc.append("hearing_outcome", {
                "specific_offence": charge.get("offence"),
                "deescription": charge.get("description"),
                "breach_number": charge.get("breach_number"),
                "prescribed_sanction": charge.get("prescribed_sanction"),
                "charge_comments": charge.get("comments"),
                "verdict": "",
                "hearing_notes": ""
            })

# Fires when workflow enters "Appeal Outcome" state
# Copies hearing_outcome rows (with verdicts) into appeal_verdict table

if doc.workflow_state == "Appeal Outcome":
    if not doc.appeal_verdict:
        for row in doc.hearing_outcome:
            doc.append("appeal_verdict", {
                "description": row.get("deescription"),
                "breach_number": row.get("breach_number"),
                "prescribed_sanction": row.get("prescribed_sanction"),
                "comments": row.get("charge_comments"),
                "original_verdict": row.get("verdict"),
                "original_verdict_notes": row.get("hearing_notes"),
                "appeal_decision": "",
                "appeal_notes": ""
            })

if not doc.is_new():

    previous_state = frappe.db.get_value(
        "Disciplinary",
        doc.name,
        "workflow_state"
    )

    frappe.log_error(
        title="DEBUG Script 1 — Issue Charge Email",
        message=f"""
workflow_state: {doc.workflow_state}
previous_state: {previous_state}
"""
    )

    if doc.workflow_state == "Issue Charge" and previous_state != "Issue Charge":

        employee_email = (
            frappe.db.get_value("Employee", doc.employee, "personal_email")
            or frappe.db.get_value("Employee", doc.employee, "company_email")
        )

        frappe.log_error(
            title="DEBUG Script 1 — Employee Email",
            message=f"""
Employee: {doc.employee}
Email: {employee_email}
"""
        )

        email_sent = False
        email_error = None

        if employee_email:

            try:

                template_name = "Disciplinary Charge Notice"

                subject = frappe.db.get_value(
                    "Email Template",
                    template_name,
                    "subject"
                )

                response_html = frappe.db.get_value(
                    "Email Template",
                    template_name,
                    "response_html"
                )

                response = frappe.db.get_value(
                    "Email Template",
                    template_name,
                    "response"
                )

                template_content = response_html or response

                frappe.log_error(
                    title="DEBUG Script 1 — Template Loaded",
                    message=f"""
Template: {template_name}
Subject: {subject}
Has HTML: {bool(response_html)}
Has Response: {bool(response)}
"""
                )

                if not template_content:
                    frappe.throw(
                        f"No content found in Email Template '{template_name}'."
                    )

                message = frappe.render_template(
                    template_content,
                    {
                        "doc": doc
                    }
                )

                frappe.sendmail(
                    recipients=[employee_email],
                    subject=subject or f"Notice of Disciplinary Charge — {doc.employee_name}",
                    message=message,
                    now=True
                )

                email_sent = True

                frappe.log_error(
                    title="DEBUG Script 1 — Email Sent",
                    message=f"""
Email successfully sent.

Recipient: {employee_email}
Template: {template_name}
"""
                )

            except Exception as e:
                email_error = str(e)
                frappe.log_error(
                    title="DEBUG Script 1 — Email Failure",
                    message=f"""
Failed to send charge notice email.

Recipient: {employee_email}
Error: {email_error}
"""
                )

        if email_sent:
            status_line = f"Charge notice sent to <b>{doc.employee_name}</b><br>Email: {employee_email}"
            heading = "✅ Charge Issued"
        elif employee_email:
            status_line = (
                f"Charge notice could <b>not</b> be emailed to <b>{doc.employee_name}</b> "
                f"({employee_email}).<br>Reason: {email_error}"
            )
            heading = "⚠️ Charge Issued — Email Not Sent"
        else:
            status_line = f"No email address found on record for <b>{doc.employee_name}</b> — no notice sent."
            heading = "⚠️ Charge Issued — Email Not Sent"

        frappe.get_doc({
            "doctype": "Comment",
            "comment_type": "Info",
            "reference_doctype": doc.doctype,
            "reference_name": doc.name,
            "content": f"""
<b>{heading}</b><br>
Issued by: <b>{doc.issued_by or doc.name_of_charging_officer or 'Not Set'}</b><br>
{status_line}<br>
Response deadline set to: <b>{doc.response_deadline or 'Not Set'}</b>
"""
        }).insert(ignore_permissions=True)

if not doc.is_new():
    previous_state = frappe.db.get_value("Disciplinary", doc.name, "workflow_state")

    frappe.log_error(
        title="DEBUG Script 4 — Issue Charge Deadline",
        message=f"workflow_state: {doc.workflow_state}\nprevious_state: {previous_state}\nresponse_deadline: {doc.response_deadline}"
    )

    if doc.workflow_state == "Issue Charge" and previous_state != "Issue Charge":

        if not doc.response_deadline:
            start = frappe.utils.today()
            count = 0
            result = start

            while count < 5:
                result = frappe.utils.add_days(result, 1)
                day_of_week = frappe.utils.getdate(result).weekday()
                if day_of_week < 5:
                    count = count + 1

            doc.response_deadline = result

            frappe.log_error(
                title="DEBUG Script 4 — Deadline Set",
                message=f"response_deadline: {doc.response_deadline}"
            )

if not doc.is_new():
    previous_state = frappe.db.get_value("Disciplinary", doc.name, "workflow_state")

    frappe.log_error(
        title="DEBUG Script 5 — Hearing Deadline",
        message=f"workflow_state: {doc.workflow_state}\nprevious_state: {previous_state}\nhearing_response_deadline: {doc.hearing_response_deadline}"
    )

    if doc.workflow_state == "Hearing Outcome" and previous_state != "Hearing Outcome":

        if not doc.hearing_response_deadline:
            start = frappe.utils.today()
            count = 0
            result = start

            while count < 5:
                result = frappe.utils.add_days(result, 1)
                day_of_week = frappe.utils.getdate(result).weekday()
                if day_of_week < 5:
                    count = count + 1

            doc.hearing_response_deadline = result

            frappe.log_error(
                title="DEBUG Script 5 — Deadline Set",
                message=f"hearing_response_deadline: {doc.hearing_response_deadline}"
            )

if not doc.is_new():
    previous_state = frappe.db.get_value("Disciplinary", doc.name, "workflow_state")

    frappe.log_error(
        title="DEBUG Script 6 — Appeal Deadline",
        message=f"workflow_state: {doc.workflow_state}\nprevious_state: {previous_state}\nappeal_response_deadline: {doc.appeal_response_deadline}"
    )

    if doc.workflow_state == "Appeal Outcome" and previous_state != "Appeal Outcome":

        if not doc.appeal_response_deadline:
            start = frappe.utils.today()
            count = 0
            result = start

            while count < 5:
                result = frappe.utils.add_days(result, 1)
                day_of_week = frappe.utils.getdate(result).weekday()
                if day_of_week < 5:
                    count = count + 1

            doc.appeal_response_deadline = result

            frappe.log_error(
                title="DEBUG Script 6 — Deadline Set",
                message=f"appeal_response_deadline: {doc.appeal_response_deadline}"
            )

disciplinary_members = [d.employee for d in doc.hearing if d.employee]

for row in doc.appeal_members:
    if row.employee and row.employee in disciplinary_members:
        frappe.throw(
            f"Employee {row.employee} cannot serve on both the Disciplinary Committee and the Appeal Committee."
        )

if doc.employee:
    doc.custom_employee_notify_email = (
        frappe.db.get_value("Employee", doc.employee, "personal_email")
        or frappe.db.get_value("Employee", doc.employee, "company_email")
    )

if doc.supervisor:
    doc.custom_supervisor_notify_email = (
        frappe.db.get_value("Employee", doc.supervisor, "personal_email")
        or frappe.db.get_value("Employee", doc.supervisor, "company_email")
    )

# At least one Disciplinary Charge is required once the case moves past the Charge stage.
if doc.workflow_state not in ("Draft", "Charge") and not doc.charge_description:
    frappe.throw("Add at least one Offence in <b>Disciplinary Charges</b> before moving the case forward.")

# Record HOW a disciplinary case was closed, and stamp/clear warning expiry.
prev_state = None if doc.is_new() else frappe.db.get_value("Disciplinary", doc.name, "workflow_state")
if doc.workflow_state == "Case Closed" and prev_state and prev_state != "Case Closed":
    closed_on = frappe.utils.nowdate()
    doc.custom_closed_on = closed_on
    doc.custom_closed_from_stage = prev_state

    outcome = "Closed (Other)"
    detail = ""
    if prev_state == "Issue Warning":
        outcome = "Warning Issued"
    elif prev_state == "Awaiting Employee Decision":
        outcome = "Hearing Verdict Accepted"
        detail = doc.hearing_decision or ""
    elif prev_state == "Appeal Under Review":
        outcome = "Appeal Rejected at Review"
    elif prev_state == "Appeal Requested":
        outcome = "Appeal Request Denied"
    elif prev_state == "Pending Outcome Approval":
        if doc.appeal_decision == "Approved":
            outcome = "Appeal Upheld"
        else:
            outcome = "Appeal Rejected"
            detail = doc.appeal_decision or ""
    else:
        detail = prev_state
    doc.custom_closure_outcome = outcome
    doc.custom_closure_detail = detail

    is_warning_outcome = (prev_state == "Issue Warning") or (prev_state == "Awaiting Employee Decision" and (doc.hearing_decision or "") == "Warning")
    verbal_m = frappe.db.get_single_value("HR Settings", "custom_verbal_warning_validity_months") or 6
    written_m = frappe.db.get_single_value("HR Settings", "custom_written_warning_validity_months") or 12
    for row in doc.charge_description:
        if is_warning_outcome:
            sanction = (row.prescribed_sanction or "").lower()
            months = 0
            if "verbal" in sanction:
                months = verbal_m
            elif "warning" in sanction:
                months = written_m
            row.warning_expiry_date = frappe.utils.add_months(closed_on, months) if months else None
        else:
            row.warning_expiry_date = None

user_roles = frappe.get_all(
    "Has Role",
    filters={"parent": user, "parenttype": "User"},
    pluck="role",
)

if user == "Administrator" or "System Manager" in user_roles:
    conditions = "1=1"
else:
    workflow_names = frappe.get_all(
        "Workflow",
        filters={"document_type": "Disciplinary", "is_active": 1},
        pluck="name",
    )

    full_visibility = False
    role_conditions = []

    if workflow_names:
        workflow_doc = frappe.get_doc("Workflow", workflow_names[0])
        for approver_row in workflow_doc.get("workflow_state_approver"):
            if approver_row.get("role") in user_roles:
                if approver_row.get("view_all_states"):
                    full_visibility = True
                else:
                    row_parts = []
                    state_val = approver_row.get("state")
                    status_val = approver_row.get("status")
                    if state_val:
                        row_parts.append("`tabDisciplinary`.workflow_state = " + frappe.db.escape(state_val))
                    if status_val:
                        row_parts.append("`tabDisciplinary`.status = " + frappe.db.escape(status_val))
                    if row_parts:
                        role_conditions.append("(" + " and ".join(row_parts) + ")")

    if full_visibility:
        conditions = "1=1"
    elif role_conditions:
        conditions = "((" + " or ".join(role_conditions) + ") or `tabDisciplinary`.owner = '%s')" % (user,)
    else:
        conditions = "`tabDisciplinary`.owner = '%s'" % (user,)
